const ocrResult = context.get('ocr_result');
const analysis = context.get('analysis');

return {
  success: true,
  document: {
    raw_text: ocrResult.text,
    formatted_markdown: ocrResult.markdown,
    blocks: ocrResult.blocks,
    analysis: analysis
  },
  metadata: {
    ocr_provider: ocrResult.provider,
    processing_time_ms: ocrResult.metadata?.processing_time_ms || 0
  }
};
